function writeMemberStatus() {
  let sheet = SpreadsheetApp.getActiveSheet()
  let duesCell = sheet.getRange("D3")
  let duesPaid = duesCell.getValue()
  let hoursCell = sheet.getRange("E3")
  let hours = Number(hoursCell.getValue())
  let status = ""
  if (duesPaid === true && hours >= 10) {
    status = "Thank you"
  } else if (duesPaid === false) {
    status = "Reminder"
  } else {
    status = "OK"
  }
  let statusCell = sheet.getRange("G3")
  statusCell.setValue(status)
}
